import { describe, expect, it, vi } from "vitest";
vi.mock("@/lib/logger", async () => (await import("./server/_support/doubles/misc")).loggerModule);
import { runCleanupArchivedJob } from "@/server/jobs/cleanup-archived-job";
import * as orgService from "@/server/services/organization-service";
import { registerActivityListeners } from "@/server/services/activity-service";
import { getDb, activityEvents, members } from "@/server/db";
import { eq } from "drizzle-orm";
import { createTenant, useTemporaryDatabase } from "./server/_support/fixtures";

describe("smoke", () => {
  it("works", async () => {
    const cleanup = await useTemporaryDatabase();
    registerActivityListeners();
    const t = await createTenant("smoke");
    await orgService.deleteOrganization(t.actors.owner, { orgId: t.org.id, confirmSlug: t.org.slug });
    await expect(orgService.deleteOrganization(t.actors.owner, { orgId: t.org.id, confirmSlug: t.org.slug })).rejects.toThrow(/already archived/);
    await expect(orgService.restoreOrganization(t.userIds.member, t.org.id)).rejects.toThrow(/denied|permission/i);
    const r = await orgService.restoreOrganization(t.userIds.owner, t.org.id);
    expect(r.archivedAt).toBeNull();
    const acts = getDb().select().from(activityEvents).where(eq(activityEvents.orgId, t.org.id)).all().map(a => a.action);
    expect(acts).toContain("organization.deleted");
    expect(acts).toContain("organization.restored");
    await orgService.deleteOrganization(t.actors.owner, { orgId: t.org.id, confirmSlug: t.org.slug });
    await runCleanupArchivedJob(new Date(Date.now() + 29 * 86400000));
    expect(getDb().select().from(members).where(eq(members.orgId, t.org.id)).all().length).toBeGreaterThan(0);
    const res = await runCleanupArchivedJob(new Date(Date.now() + 31 * 86400000));
    expect(res.failed).toBe(0);
    expect(getDb().select().from(members).where(eq(members.orgId, t.org.id)).all().length).toBe(0);
    await expect(orgService.restoreOrganization(t.userIds.owner, t.org.id)).rejects.toThrow(/not found/);
    cleanup();
  });
});
EOF
